	virtual void _resizeEvent(const Pt::Gui::ResizeEvent& event)
	{
		_image.resize(  event.width(), event.height(), Pt::Gfx::ARgbColor( 0xffff, 0xffff, 0xffff ) );
	}

	void drawTextBoundingRect()
	{
		Pt::Gfx::Pen					pen( 10,  Pt::Gfx::ARgbColor( 0, 0, 0xffff ) );
		Pt::Gfx::FontMetrics			metrics;
		std::vector<Pt::Gfx::Point>	polygon;
		Pt::String				        text = L"Wuerzburg";

		_imagePainter.drawText( Pt::Gfx::Point(50,50), text );
		metrics = _imagePainter.fontMetrics( text );

		polygon.push_back( Pt::Gfx::Point( 50, 50 + metrics.descent() ) );
		polygon.push_back( Pt::Gfx::Point( 50 , 50 - metrics.height() ));
		polygon.push_back( Pt::Gfx::Point( 50 + metrics.width(),  50 - metrics.height() ) );
		polygon.push_back( Pt::Gfx::Point( 50 + metrics.width(),  50  + metrics.descent()));
		polygon.push_back( Pt::Gfx::Point( 50, 50 + metrics.descent() ) );

		_imagePainter.drawPolyline( &polygon[0], polygon.size() );

		painter().drawImage( Pt::Gfx::Point( 0, 0 ), _image );
	}

